// ─── File: AsyncTransferDemo.java ───
// Runnable demo of accept-then-process with 202 Accepted and a background worker.
package com.bank.asynctransfer;

import java.math.BigDecimal;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.*;
import java.util.logging.*;

public class AsyncTransferDemo {

    private static final Logger log = Logger.getLogger("AsyncTransfer");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        log.setUseParentHandlers(false);
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        JobStore store = new JobStore();
        BlockingQueue<String> queue = new LinkedBlockingQueue<>();
        TransferWorker worker = new TransferWorker(store, queue);
        worker.start();

        TransferController controller = new TransferController(store, queue);

        // Client submits an international transfer; endpoint returns IMMEDIATELY.
        TransferRequest req = new TransferRequest("SAV2001", "GB29-NWBK-INTL",
                new BigDecimal("50000"), "idem-rajesh-001");
        AcceptedResponse accepted = controller.submit(req);
        log.info(() -> "CLIENT got 202 Accepted, track at " + accepted.statusUrl());

        // Client polls status while the worker processes in the background.
        for (int i = 0; i < 5; i++) {
            TimeUnit.MILLISECONDS.sleep(300);
            TransferJob job = store.find(accepted.jobId());
            log.info(() -> "CLIENT polled status = " + job.getStatus());
            if (job.getStatus() == TransferJob.Status.COMPLETED
                    || job.getStatus() == TransferJob.Status.FAILED) break;
        }
        worker.shutdown();
    }
}

// ─── api/TransferRequest.java ───
record TransferRequest(String fromAccount, String toIban,
                       BigDecimal amount, String idempotencyKey) { }

// ─── api/AcceptedResponse.java ───
record AcceptedResponse(String jobId, String statusUrl) { }

// ─── job/TransferJob.java (durable job with status lifecycle) ───
class TransferJob {
    enum Status { PENDING, PROCESSING, COMPLETED, FAILED }
    private final String jobId;
    private final TransferRequest request;
    private volatile Status status = Status.PENDING;
    TransferJob(String jobId, TransferRequest request) {
        this.jobId = jobId; this.request = request;
    }
    String getJobId() { return jobId; }
    TransferRequest getRequest() { return request; }
    Status getStatus() { return status; }
    void setStatus(Status s) { this.status = s; }
}

// ─── job/JobStore.java (durable record; in prod this is a DB table) ───
class JobStore {
    private final Map<String, TransferJob> db = new ConcurrentHashMap<>();
    private final Map<String, String> byIdemKey = new ConcurrentHashMap<>();
    // Returns existing job for a repeated idempotency key (no duplicate work).
    TransferJob saveNewOrExisting(TransferRequest req) {
        String existing = byIdemKey.get(req.idempotencyKey());
        if (existing != null) return db.get(existing);
        String id = "TXF-" + UUID.randomUUID().toString().substring(0, 8);
        TransferJob job = new TransferJob(id, req);
        db.put(id, job);
        byIdemKey.put(req.idempotencyKey(), id);
        return job;
    }
    TransferJob find(String id) { return db.get(id); }
}

// ─── api/TransferController.java (fast accept path only) ───
class TransferController {
    private static final Logger log = Logger.getLogger("AsyncTransfer");
    private final JobStore store;
    private final BlockingQueue<String> queue;
    TransferController(JobStore store, BlockingQueue<String> queue) {
        this.store = store; this.queue = queue;
    }
    // Validate → persist PENDING → enqueue → return 202. Thread released in ms.
    AcceptedResponse submit(TransferRequest req) {
        if (req.amount().signum() <= 0) throw new IllegalArgumentException("amount>0");
        TransferJob job = store.saveNewOrExisting(req);
        queue.offer(job.getJobId());
        log.info(() -> "ACCEPTED job " + job.getJobId() + " (PENDING), returning 202");
        return new AcceptedResponse(job.getJobId(),
                "/api/v1/transfers/" + job.getJobId() + "/status");
    }
}

// ─── worker/TransferWorker.java (slow processing in the background) ───
class TransferWorker extends Thread {
    private static final Logger log = Logger.getLogger("AsyncTransfer");
    private final JobStore store;
    private final BlockingQueue<String> queue;
    private volatile boolean running = true;
    TransferWorker(JobStore store, BlockingQueue<String> queue) {
        this.store = store; this.queue = queue; setDaemon(true);
    }
    @Override public void run() {
        while (running) {
            try {
                String jobId = queue.poll(200, TimeUnit.MILLISECONDS);
                if (jobId == null) continue;
                TransferJob job = store.find(jobId);
                job.setStatus(TransferJob.Status.PROCESSING);
                log.info(() -> "WORKER processing " + jobId + " (SWIFT + fraud checks)");
                TimeUnit.MILLISECONDS.sleep(700);   // simulate slow SWIFT work
                job.setStatus(TransferJob.Status.COMPLETED);
                log.info(() -> "WORKER completed " + jobId);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt(); running = false;
            }
        }
    }
    void shutdown() { running = false; }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
